# SPDX-License-Identifier: MIT
# Writes the committed texture conformance fixtures. Panic classification comes from the
# differential probe transcripts, recorded as boolean `.fails` values.
import sys
sys.path.insert(0, sys.argv[2]); from model import parse
out = sys.argv[1]
names = [l.strip() for l in open(sys.argv[3]) if l.strip()]
HEAD = '''-- SPDX-License-Identifier: MIT
-- Generated by tests/fixtures/c7f/gen_fixtures.py. Records named *.fails are SF Rust panics
-- (message-less in SF, Lua errors in Kiln, which never lets a panic reach Lua): only the failure itself is compared.
local names = {%s}
local function hex(s) return (s:gsub('.', function(c) return string.format('%%02x', string.byte(c)) end)) end
local function digest(s) return #s, hasher.crc64(s), hex(s:sub(1, 24)) end
local function lcg(seed)
    local x = seed
    return function() x = (x * 1103515245 + 12345) & 0x7fffffff; return (x >> 16) & 255 end
end
local function bytes(n, seed)
    local r, t = lcg(seed), {}
    for i = 1, n do t[i] = string.char(r()) end
    return table.concat(t)
end
local function pixels(i)
    local t = {}
    for y = 0, i.height - 1 do for x = 0, i.width - 1 do
        local r, g, b, a = i:get_pixel(x, y); t[#t + 1] = string.char(r, g, b, a)
    end end
    return table.concat(t)
end
local function image_of(w, h, data)
    local i, k = image.create(w, h), 1
    for y = 0, h - 1 do for x = 0, w - 1 do
        i:set_pixel(x, y, data:byte(k), data:byte(k + 1), data:byte(k + 2), data:byte(k + 3)); k = k + 4
    end end
    return i
end
local function fails(label, fn, ...) T.value(label .. '.fails', not pcall(fn, ...)) end
''' % ",".join('"%s"' % n for n in names)

def info(n):
    p = parse(n)
    return p if p and p[0] else None
REFUSED = lambda n: n == 'None' or n.startswith(('A2', 'D', 'S8', 'X8')) or '_srgb' in n and not n.startswith('BC') or n == 'BC6H_sfloat_block'
def bpp(n):
    if n.startswith('BC'): return None
    if n in ('B10G11R11_ufloat_pack32', 'E5B9G9R9_ufloat_pack32'): return 4
    if n.endswith('pack8'): return 1
    if n.endswith('pack16'): return 2
    order, size, kind = info(n); return size // 8 * len(order)
def wide_int(n):
    p = info(n); return p and p[1] >= 32 and p[2] in ('uint', 'sint')

# ---------------- encode ----------------
E = [HEAD, r'''
local rows = {}
for c = 1, 4 do for x = 0, 255 do local p = {0, 0, 0, 0}; p[c] = x; rows[#rows + 1] = string.char(p[1], p[2], p[3], p[4]) end end
for x = 0, 255 do rows[#rows + 1] = string.char(x, x, x, x) end
for x = 0, 255 do rows[#rows + 1] = string.char(x, 255 - x, x ~ 0x55, (x * 7) & 255) end
local sweep = image_of(256, 6, table.concat(rows))
local small = image_of(3, 2, bytes(24, 7))
local one = image.create(1, 1)
local bc = {{4, 4, 11}, {8, 8, 12}, {16, 8, 13}, {12, 4, 14}}
''']
for n in names:
    if n == 'None':
        E.append("fails('enc.None', image.encode_texture, one, 'None')")
        E.append("fails('enc.None.0x0', image.encode_texture, image.create(0, 0), 'None')")
        continue
    if REFUSED(n) or n in ('B10G11R11_ufloat_pack32', 'E5B9G9R9_ufloat_pack32'):
        E.append("T.call('enc.%s', image.encode_texture, sweep, '%s')" % (n, n))
        E.append("T.call('enc.%s.0x0', image.encode_texture, image.create(0, 0), '%s')" % (n, n))
        continue
    if n.startswith('BC'):
        E.append("for _, d in ipairs(bc) do T.call('enc.%s.'..d[1]..'x'..d[2], function() return digest(image.encode_texture(image_of(d[1], d[2], bytes(d[1] * d[2] * 4, d[3])), '%s'):to_string()) end) end" % (n, n))
        for w, h in ((0, 0), (4, 0), (0, 8)):
            E.append("T.call('enc.%s.%dx%d', function() return digest(image.encode_texture(image.create(%d, %d), '%s'):to_string()) end)" % (n, w, h, w, h, n))
        for w, h in ((8, 3), (5, 4), (1, 1), (5, 0)):
            E.append("fails('enc.%s.%dx%d', image.encode_texture, image.create(%d, %d), '%s')" % (n, w, h, w, h, n))
        continue
    order, size, kind = info(n) or (None, 8, 'unorm')
    narrow = n.endswith(('pack8', 'pack16')) or size == 8 or kind in ('unorm', 'uscaled', 'uint')
    if narrow:
        E.append("T.call('enc.%s', function() return digest(image.encode_texture(sweep, '%s'):to_string()) end)" % (n, n))
        E.append("T.call('enc.%s.3x2', function() return digest(image.encode_texture(small, '%s'):to_string()) end)" % (n, n))
    else:
        E.append("fails('enc.%s', image.encode_texture, sweep, '%s')" % (n, n))
        E.append("fails('enc.%s.2x1', image.encode_texture, image.create(2, 1), '%s')" % (n, n))
        if len(order) == 1:
            E.append(("do local t = {} for v = 0, 255 do local i = image.create(1, 1); i:set_pixel(0, 0, v, 255 - v, v ~ 0x55, 7)"
                      " t[#t + 1] = image.encode_texture(i, '%s'):to_string() end T.value('enc.%s.single', hasher.crc64(table.concat(t))); T.value('enc.%s.single128', hex(t[129])) end") % (n, n, n))
        else:
            E.append("fails('enc.%s.1x1', image.encode_texture, one, '%s')" % (n, n))
    E.append("T.call('enc.%s.0x0', function() return digest(image.encode_texture(image.create(0, 0), '%s'):to_string()) end)" % (n, n))
open(out + '/encode.lua', 'w').write("\n".join(E) + "\n")

# ---------------- decode ----------------
D = [HEAD, "local function dec(data, n, w, h) return digest(pixels(image.decode_texture(data, n, w, h))) end"]
for n in names:
    if REFUSED(n):
        D.append("fails('dec.%s', image.decode_texture, string.rep('\\0', 64), '%s', 1, 1)" % (n, n))
        D.append("fails('dec.%s.0x0', image.decode_texture, '', '%s', 0, 0)" % (n, n))
        continue
    if n.startswith('BC'):
        bs = 8 if n.startswith(('BC1', 'BC4')) else 16
        D.append("do local d = bytes(%d, %d)" % (bs * 16, len(n)))
        D.append("  T.call('dec.%s.16x16', dec, d, '%s', 16, 16)" % (n, n))
        D.append("  T.call('dec.%s.8x4.long', dec, d, '%s', 8, 4)" % (n, n))
        D.append("  T.call('dec.%s.0x5', dec, '', '%s', 0, 5)" % (n, n))
        D.append("  fails('dec.%s.short', image.decode_texture, d:sub(1, %d), '%s', 16, 16)" % (n, bs * 16 - 1, n))
        for w, h in ((5, 4), (4, 3), (1, 1)):
            D.append("  fails('dec.%s.%dx%d', image.decode_texture, d, '%s', %d, %d)" % (n, w, h, n, w, h))
        D.append("end")
        continue
    b = bpp(n)
    D.append("do local d = bytes(%d, %d)" % (b * 1024, b * 31 + len(n)))
    if wide_int(n):
        D.append("  fails('dec.%s', image.decode_texture, d, '%s', 32, 32)" % (n, n))
        D.append("  fails('dec.%s.1x1', image.decode_texture, d, '%s', 1, 1)" % (n, n))
        D.append("  T.call('dec.%s.0x3', dec, '', '%s', 0, 3)" % (n, n))
    else:
        D.append("  T.call('dec.%s', dec, d, '%s', 32, 32)" % (n, n))
        D.append("  T.call('dec.%s.long', dec, d, '%s', 5, 3)" % (n, n))
        D.append("  T.call('dec.%s.0x0', dec, '', '%s', 0, 0)" % (n, n))
        D.append("  fails('dec.%s.short', image.decode_texture, d:sub(1, %d), '%s', 32, 32)" % (n, b * 1024 - 1, n))
    D.append("end")
D.append(r'''
for _, n in ipairs({'R16_unorm', 'R16_snorm', 'R16_uscaled', 'R16_sscaled', 'R16_uint', 'R16_sint', 'R16_sfloat', 'R16G16B16A16_sfloat'}) do
    local t = {}
    for v = 0, 65535 do t[#t + 1] = string.pack('<I2', v) end
    local w = n:find('A16') and 128 or 256
    T.call('all16.' .. n, dec, table.concat(t), n, w, (n:find('A16') and 16384 or 65536) // w)
end
local f32, f64 = {}, {}
for k = 0, 256 do
    local b32 = string.unpack('<I4', string.pack('<f', k / 255))
    local b64 = string.unpack('<i8', string.pack('<d', k / 255))
    for d = -3, 3 do
        f32[#f32 + 1] = string.pack('<I4', (b32 + d) & 0xffffffff)
        f64[#f64 + 1] = string.pack('<i8', b64 + d < 0 and 0 or b64 + d)
    end
end
local specials = {1 / 0, -1 / 0, 0 / 0, 1e30, -1e30, 255.0, -0.0, 0.5}
for _, v in ipairs(specials) do f32[#f32 + 1] = string.pack('<f', v); f64[#f64 + 1] = string.pack('<d', v) end
T.call('bound.R32_sfloat', dec, table.concat(f32), 'R32_sfloat', #f32, 1)
T.call('bound.R64_sfloat', dec, table.concat(f64), 'R64_sfloat', #f64, 1)
T.call('bound.R32G32B32A32_sfloat', dec, table.concat(f32, '', 1, 1796), 'R32G32B32A32_sfloat', 449, 1)
T.call('bound.R64G64B64A64_sfloat', dec, table.concat(f64, '', 1, 1796), 'R64G64B64A64_sfloat', 449, 1)
for _, n in ipairs({'B10G11R11_ufloat_pack32', 'E5B9G9R9_ufloat_pack32'}) do
    local walk, mix = {}, {}
    for v = 0, 2047 do walk[#walk + 1] = string.pack('<I4', v); walk[#walk + 1] = string.pack('<I4', v << 11) end
    for v = 0, 1023 do walk[#walk + 1] = string.pack('<I4', v << 22) end
    for v = 0, 4095 do mix[#mix + 1] = string.pack('<I4', (v * 2654435761) & 0xffffffff) end
    T.call('walk.' .. n, dec, table.concat(walk), n, #walk, 1)
    T.call('mix.' .. n, dec, table.concat(mix), n, 64, 64)
end
''')
open(out + '/decode.lua', 'w').write("\n".join(D) + "\n")

# ---------------- arguments ----------------
A = [HEAD, r'''
local rgba = '\1\2\3\4\5\6\7\8'
local function px(i) return i.width, i.height, hex(pixels(i)) end
for _, m in ipairs({{'nil', nil}, {'0', 0}, {'1', 1}, {'7', 7}, {'neg', -1}, {'frac', 1.5}, {'str', 'x'}, {'numstr', '3'}, {'tbl', {}}, {'bool', true}, {'big', 4294967296}, {'float_int', 2.0}}) do
    T.call('mip.' .. m[1], function() return px(image.decode_texture(rgba, 'R8G8B8A8_unorm', 2, 1, m[2])) end)
end
T.call('mip.extra', function() return px(image.decode_texture(rgba, 'R8G8B8A8_unorm', 2, 1, nil, 'extra')) end)
T.call('order.format_before_mip', image.decode_texture, rgba, 'nope', 2, 1, 'x')
T.call('order.height_before_mip', image.decode_texture, rgba, 'R8_unorm', 2, -1, 'x')
T.call('order.mip_before_codec', image.decode_texture, '', 'R8_unorm', 2, 1, 'x')
T.call('order.mip_before_refusal', image.decode_texture, '', 'R8_srgb', 2, 1, 'x')
T.call('name.lower', image.decode_texture, rgba, 'r8g8b8a8_unorm', 2, 1)
T.call('name.space', image.decode_texture, rgba, 'R8G8B8A8_unorm ', 2, 1)
T.call('name.nonutf8', image.decode_texture, rgba, '\255', 2, 1)
T.call('name.nil', image.decode_texture, rgba, nil, 2, 1)
T.call('name.number', image.decode_texture, rgba, 5, 2, 1)
T.call('data.nil', image.decode_texture, nil, 'R8G8B8A8_unorm', 2, 1)
T.call('data.table', image.decode_texture, {}, 'R8G8B8A8_unorm', 2, 1)
T.call('data.number', image.decode_texture, 12, 'R8_unorm', 2, 1)
T.call('width.nil', image.decode_texture, rgba, 'R8G8B8A8_unorm')
T.call('height.nil', image.decode_texture, rgba, 'R8G8B8A8_unorm', 2)
T.call('width.neg', image.decode_texture, rgba, 'R8G8B8A8_unorm', -2, 1)
T.call('width.frac', image.decode_texture, rgba, 'R8G8B8A8_unorm', 2.5, 1)
T.call('width.big', image.decode_texture, rgba, 'R8G8B8A8_unorm', 4294967296, 1)
T.call('width.str', function() return px(image.decode_texture(rgba, 'R8G8B8A8_unorm', '2', '1')) end)
T.call('method', function() return image:decode_texture(rgba, 'R8_unorm', 1, 1) end)
fails('dim.wrap', image.decode_texture, rgba, 'R8G8B8A8_unorm', 65536, 65536)
fails('dim.wrap_small', image.decode_texture, rgba, 'R8G8B8A8_unorm', 1073741825, 1)
fails('dim.max', image.decode_texture, rgba, 'R8_unorm', 4294967295, 4294967295)
fails('dim.empty', image.decode_texture, '', 'R8G8B8A8_unorm', 1, 1)
T.call('dim.zero_w', function() return px(image.decode_texture(rgba, 'R8G8B8A8_unorm', 0, 5)) end)
T.call('dim.zero_h', function() return px(image.decode_texture(rgba, 'R8G8B8A8_unorm', 5, 0)) end)
local b = buffer.wrap('XY' .. rgba)
b:head(2)
T.call('buf.unread', function() return px(image.decode_texture(b, 'R8G8B8A8_unorm', 2, 1)) end)
T.value('buf.head_after', b:head())
T.value('buf.remaining_after', b:remaining())
local w = buffer.create(); w:write_string(rgba)
T.call('buf.writer', function() return px(image.decode_texture(w, 'R8G8B8A8_unorm', 2, 1)) end)
T.value('buf.writer_remaining', w:remaining())
local c = buffer.wrap(rgba); c:close()
T.call('buf.closed', image.decode_texture, c, 'R8G8B8A8_unorm', 2, 1)
T.call('buf.closed_before_name', image.decode_texture, c, 'nope', 2, 1)
local i1, i2 = image.decode_texture(rgba, 'R8G8B8A8_unorm', 2, 1), image.decode_texture(rgba, 'R8G8B8A8_unorm', 2, 1)
T.value('dec.fresh', rawequal(i1, i2))
T.value('dec.typeof', typeof(i1))
i1:set_pixel(0, 0, 9, 9, 9, 9)
T.call('dec.independent', px, i2)
local img = image_of(2, 1, rgba)
T.call('enc.badname', image.encode_texture, img, 'nope')
T.call('enc.nofmt', image.encode_texture, img)
T.call('enc.noimage', image.encode_texture, nil, 'R8_unorm')
T.call('enc.string', image.encode_texture, rgba, 'R8_unorm')
T.call('enc.buffer', image.encode_texture, buffer.wrap(rgba), 'R8_unorm')
T.call('enc.method', function() return image:encode_texture(img, 'R8_unorm') end)
T.call('enc.extra', function() local e = image.encode_texture(img, 'R8G8B8A8_unorm', 5); return typeof(e), e:remaining(), e:head(), hex(e:to_string()) end)
local e1, e2 = image.encode_texture(img, 'R8_unorm'), image.encode_texture(img, 'R8_unorm')
T.value('enc.fresh', rawequal(e1, e2))
T.call('enc.writable', function() e1:write_u8(0xab); return e1:remaining(), hex(e1:to_string()) end)
T.call('enc.source_unchanged', px, img)
T.call('roundtrip', function() return px(image.decode_texture(image.encode_texture(img, 'B8G8R8A8_unorm'), 'B8G8R8A8_unorm', 2, 1)) end)
T.value('alias', rawequal(image.decode_texture, builtin.image.decode_texture) and rawequal(image.encode_texture, builtin.image.encode_texture))
T.value('types', type(image.decode_texture) .. ' ' .. type(image.encode_texture))
''']
open(out + '/arguments.lua', 'w').write("\n".join(A) + "\n")
